    function valid(row) { return row && ['inside','outside','perm'].every(function(k) { return typeof row[k] === 'number' && Number.isFinite(row[k]) && row[k] >= 0 && row[k] <= (k === 'perm' ? 100 : 200); }) && ['animal','plant'].indexOf(row.cellType) >= 0; }
